):
    db_project = crud.get_project(db, project_id=project_id)
    if db_project is None or db_project.owner_id != current_user.id:
        # TODO: Add logic to check project share permissions
        raise HTTPException(status_code=403, detail="Not authorized to view tasks in this project")
    tasks = crud.get_tasks(db, project_id=project_id, skip=skip, limit=limit)
    return tasks

