router = APIRouter()

@router.post("/comments/", response_model=schemas.Comment, status_code=status.HTTP_201_CREATED)
def create_comment(
    comment: schemas.CommentCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    if not (comment.project_id or comment.task_id or comment.subtask_id):
        raise HTTPException(status_code=400, detail="Comment must be associated with a project, task, or subtask")

    # Validate parent entity and user permissions
    if comment.project_id:
        db_project = crud.get_project(db, project_id=comment.project_id)
        if db_project is None or db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to comment on this project")
    elif comment.task_id:
        db_task = crud.get_task(db, task_id=comment.task_id)
        if db_task is None:
            raise HTTPException(status_code=404, detail="Task not found")
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to comment on this task")
    elif comment.subtask_id:
        db_subtask = crud.get_subtask(db, subtask_id=comment.subtask_id)
        if db_subtask is None:
            raise HTTPException(status_code=404, detail="Subtask not found")
        db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to comment on this subtask")

    return crud.create_comment(db=db, comment=comment, owner_id=current_user.id)

@router.get("/comments/{item_id}", response_model=list[schemas.Comment])
def get_comments_for_item(
    item_id: int,
    item_type: str, # "project", "task", "subtask"
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    comments = []
    if item_type == "project":
        db_project = crud.get_project(db, project_id=item_id)
        if db_project is None:
            raise HTTPException(status_code=404, detail="Project not found")
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to view comments for this project")
        comments = crud.get_comments_for_item(db, project_id=item_id)
    elif item_type == "task":
        db_task = crud.get_task(db, task_id=item_id)
        if db_task is None:
            raise HTTPException(status_code=404, detail="Task not found")
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to view comments for this task")
        comments = crud.get_comments_for_item(db, task_id=item_id)
    elif item_type == "subtask":
        db_subtask = crud.get_subtask(db, subtask_id=item_id)
        if db_subtask is None:
            raise HTTPException(status_code=404, detail="Subtask not found")
        db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to view comments for this subtask")
        comments = crud.get_comments_for_item(db, subtask_id=item_id)
    else:
        raise HTTPException(status_code=400, detail="Invalid item_type specified. Must be 'project', 'task', or 'subtask'.")

    return comments

@router.delete("/comments/{comment_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_comment(
    comment_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_comment = crud.get_comment(db, comment_id=comment_id)
    if db_comment is None:
        raise HTTPException(status_code=404, detail="Comment not found")

    if db_comment.owner_id != current_user.id:
        # Allow project owners or admins to delete comments as well
        # Determine the parent project of the comment and check permissions
        project_id_to_check = None
        if db_comment.project_id:
            project_id_to_check = db_comment.project_id
        elif db_comment.task_id:
            task = crud.get_task(db, task_id=db_comment.task_id)
            if task:
                project_id_to_check = task.project_id
        elif db_comment.subtask_id:
            subtask = crud.get_subtask(db, subtask_id=db_comment.subtask_id)
            if subtask:
                task = crud.get_task(db, task_id=subtask.parent_task_id)
                if task:
                    project_id_to_check = task.project_id

        if project_id_to_check:
            db_project = crud.get_project(db, project_id=project_id_to_check)
            if db_project and db_project.owner_id == current_user.id:
                # Project owner can delete any comment within their project
                pass
            else:
                # TODO: Check project share permissions for admin/edit roles
                raise HTTPException(status_code=403, detail="Not authorized to delete this comment")
        else:
            raise HTTPException(status_code=403, detail="Not authorized to delete this comment")

    crud.delete_comment(db=db, comment_id=comment_id)
    return

