from sqlalchemy.orm import Session
import models, schemas

def get_subtask(db: Session, subtask_id: int):
    return db.query(models.Subtask).filter(models.Subtask.id == subtask_id).first()

def get_subtasks(db: Session, parent_task_id: int, skip: int = 0, limit: int = 100):
    return db.query(models.Subtask).filter(models.Subtask.parent_task_id == parent_task_id).offset(skip).limit(limit).all()

def create_subtask(db: Session, subtask: schemas.SubtaskCreate):
    db_subtask = models.Subtask(**subtask.model_dump())
    db.add(db_subtask)
    db.commit()
    db.refresh(db_subtask)
    return db_subtask

def update_subtask(db: Session, subtask_id: int, subtask: schemas.SubtaskUpdate):
    db_subtask = db.query(models.Subtask).filter(models.Subtask.id == subtask_id).first()
    if not db_subtask:
        return None
    for var, value in subtask.model_dump(exclude_unset=True).items():
        setattr(db_subtask, var, value)
    db.add(db_subtask)
    db.commit()
    db.refresh(db_subtask)
    return db_subtask

def delete_subtask(db: Session, subtask_id: int):
    db_subtask = db.query(models.Subtask).filter(models.Subtask.id == subtask_id).first()
    if not db_subtask:
        return None
    db.delete(db_subtask)
    db.commit()
    return db_subtask

