import api from './api';
import { Attachment } from '../types/attachment';

export const uploadAttachment = async (
  file: File,
  association: { project_id?: number; task_id?: number; subtask_id?: number }
): Promise<Attachment> => {
  const formData = new FormData();
  formData.append('file', file);
  if (association.project_id) formData.append('project_id', association.project_id.toString());
  if (association.task_id) formData.append('task_id', association.task_id.toString());
  if (association.subtask_id) formData.append('subtask_id', association.subtask_id.toString());

  const response = await api.post<Attachment>('/attachments/upload', formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
  return response.data;
};

export const downloadAttachment = async (attachmentId: number, filename: string) => {
    const response = await api.get(`/attachments/${attachmentId}/download`, {
        responseType: 'blob',
    });

    // Create a URL for the blob
    const url = window.URL.createObjectURL(new Blob([response.data]));
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    link.remove();
};

export const deleteAttachment = async (attachmentId: number): Promise<void> => {
    await api.delete(`/attachments/${attachmentId}`);
};

