import React, { useState } from 'react';
import { Button, CircularProgress, Typography, Box, Alert } from '@mui/material';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import { uploadAttachment } from '../../services/attachmentService';

interface AttachmentUploadProps {
  association: { project_id?: number; task_id?: number; subtask_id?: number };
  onUploadSuccess: () => void;
}

const AttachmentUpload: React.FC<AttachmentUploadProps> = ({ association, onUploadSuccess }) => {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files.length > 0) {
      const file = event.target.files[0];
      setUploading(true);
      setError(null);

      try {
        await uploadAttachment(file, association);
        onUploadSuccess();
      } catch (err) {
        console.error("Upload failed", err);
        setError("Failed to upload file. Please try again.");
      } finally {
        setUploading(false);
        // Reset the input value so the same file can be selected again if needed
        event.target.value = '';
      }
    }
  };

  return (
    <Box>
      <input
        accept="*/*"
        style={{ display: 'none' }}
        id="raised-button-file"
        multiple={false}
        type="file"
        onChange={handleFileChange}
      />
      <label htmlFor="raised-button-file">
        <Button
          variant="outlined"
          component="span"
          startIcon={uploading ? <CircularProgress size={20} /> : <CloudUploadIcon />}
          disabled={uploading}
        >
          {uploading ? 'Uploading...' : 'Upload File'}
        </Button>
      </label>
      {error && (
        <Alert severity="error" sx={{ mt: 1 }}>
          {error}
        </Alert>
      )}
    </Box>
  );
};

export default AttachmentUpload;

import React from 'react';
import { List, ListItem, ListItemIcon, ListItemText, IconButton, Typography, Box } from '@mui/material';
import InsertDriveFileIcon from '@mui/icons-material/InsertDriveFile';
import DownloadIcon from '@mui/icons-material/Download';
import DeleteIcon from '@mui/icons-material/Delete';
import { Attachment } from '../../types/attachment';
import { downloadAttachment, deleteAttachment } from '../../services/attachmentService';
import { useMutation, useQueryClient } from '@tanstack/react-query';

interface AttachmentListProps {
  attachments: Attachment[];
  canDelete?: boolean; // Optional prop to control delete permission visual
}

const AttachmentList: React.FC<AttachmentListProps> = ({ attachments, canDelete = true }) => {
  const queryClient = useQueryClient();

  const deleteMutation = useMutation({
    mutationFn: deleteAttachment,
    onSuccess: () => {
      // Invalidate queries to refresh the list
      // Note: The parent component should be using useQuery with a key that we can invalidate here
      // But for generic usage, we might just rely on the parent refetching or invalidating generic keys
      queryClient.invalidateQueries({ queryKey: ['attachments'] }); 
    },
  });

  const handleDownload = (attachment: Attachment) => {
    downloadAttachment(attachment.id, attachment.filename);
  };

  const handleDelete = (id: number) => {
    if (window.confirm('Are you sure you want to delete this attachment?')) {
        deleteMutation.mutate(id);
    }
  };

  if (!attachments || attachments.length === 0) {
    return <Typography variant="body2" color="textSecondary">No attachments yet.</Typography>;
  }

  return (
    <List dense>
      {attachments.map((attachment) => (
        <ListItem key={attachment.id}
          secondaryAction={
            <Box>
                <IconButton edge="end" aria-label="download" onClick={() => handleDownload(attachment)}>
                <DownloadIcon />
                </IconButton>
                {canDelete && (
                    <IconButton edge="end" aria-label="delete" onClick={() => handleDelete(attachment.id)}>
                    <DeleteIcon />
                    </IconButton>
                )}
            </Box>
          }
        >
          <ListItemIcon>
            <InsertDriveFileIcon />
          </ListItemIcon>
          <ListItemText
            primary={attachment.filename}
