from typing import Annotated
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session
import crud, schemas, models
from database import get_db
from utils.auth_utils import get_current_active_superuser # Import the new dependency

router = APIRouter(prefix="/admin", tags=["admin"])

# --- Tag Management ---
@router.post("/tags/", response_model=schemas.Tag, status_code=status.HTTP_201_CREATED)
def create_tag(
    tag: schemas.TagCreate,
    db: Annotated[Session, Depends(get_db)],
    current_superuser: Annotated[models.User, Depends(get_current_active_superuser)],
):
    db_tag = crud.get_tag_by_name(db, name=tag.name)
    if db_tag:
        raise HTTPException(status_code=400, detail="Tag name already registered")
    return crud.create_tag(db=db, tag=tag)

@router.get("/tags/", response_model=list[schemas.Tag])
def read_tags(
    db: Annotated[Session, Depends(get_db)],
    current_superuser: Annotated[models.User, Depends(get_current_active_superuser)],
    skip: int = 0, limit: int = 100
):
    tags = crud.get_tags(db, skip=skip, limit=limit)
    return tags

@router.get("/tags/{tag_id}", response_model=schemas.Tag)
def read_tag(
    tag_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_superuser: Annotated[models.User, Depends(get_current_active_superuser)],
):
    db_tag = crud.get_tag(db, tag_id=tag_id)
    if db_tag is None:
        raise HTTPException(status_code=404, detail="Tag not found")
    return db_tag

@router.put("/tags/{tag_id}", response_model=schemas.Tag)
def update_tag(
