import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { getProjectById, deleteProject } from '../services/projects';
import { getTasks } from '../services/tasks';
import {
  Container,
  Grid,
  Paper,
  Typography,
  Box,
  Button,
  Chip,
  IconButton,
  LinearProgress,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import CreateTaskModal from '../components/tasks/CreateTaskModal';
import EditProjectModal from '../components/projects/EditProjectModal';
import EditTaskModal from '../components/tasks/EditTaskModal';
import ProjectGanttChart from '../components/projects/ProjectGanttChart';
import { format, isValid } from 'date-fns';

const safeFormat = (dateStr: string | undefined, fmt: string) => {
  if (!dateStr) return 'Not set';
  const d = new Date(dateStr);
  return isValid(d) ? format(d, fmt) : 'Invalid Date';
};

const ProjectDetailPage = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  // Modal States
  const [isCreateTaskModalOpen, setIsCreateTaskModalOpen] = useState(false);
  const [isEditProjectModalOpen, setIsEditProjectModalOpen] = useState(false);
  const [isEditTaskModalOpen, setIsEditTaskModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<any>(null); // State to hold task being edited

  console.log("ProjectDetailPage rendering...");

  const {
    data: project,
    isLoading: isLoadingProject,
    error: projectError
  } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => getProjectById(projectId!),
    enabled: !!projectId,
  });

  const {
    data: tasks,
    isLoading: isLoadingTasks,
    error: tasksError
  } = useQuery({
    queryKey: ['tasks', projectId],
    queryFn: () => getTasks(projectId!),
    enabled: !!projectId,
  });

  console.log("Data loaded:", { project, tasks, isLoadingProject, isLoadingTasks, projectError, tasksError });

  // const updateMutation = useMutation({
  //   mutationFn: (data: { name: string, description?: string }) => updateProject(projectId!, data),
  //   onSuccess: () => {
  //     queryClient.invalidateQueries({ queryKey: ['project', projectId] });
  //   },
  // });

  const deleteMutation = useMutation({
    mutationFn: () => deleteProject(projectId!),
    onSuccess: () => {
      navigate('/projects');
    },
  });

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      deleteMutation.mutate();
    }
  };

  // Handlers for Task Edit
  const handleEditTask = (task: any) => {
    setSelectedTask(task);
    setIsEditTaskModalOpen(true);
  };

  if (isLoadingProject || isLoadingTasks) {
    return (
      <Container>
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
          <CircularProgress />
        </Box>
      </Container>
    );
  }

  if (projectError || !project) {
    return (
      <Container>
        <Typography color="error" sx={{ mt: 4 }}>
          Error loading project or project not found.
        </Typography>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/projects')}>
          Back to Projects
        </Button>
      </Container>
    );
  }

  const progress = project.progress !== undefined ? project.progress : 0;

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      {/* Header Section */}
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 4 }}>
        <IconButton onClick={() => navigate('/projects')} sx={{ mr: 2 }}>
          <ArrowBackIcon />
        </IconButton>
        <Box sx={{ flexGrow: 1 }}>
          <Typography variant="h4" component="h1" gutterBottom>
            {project.name}
          </Typography>
          <Typography variant="body1" color="text.secondary">
            {project.description}
          </Typography>
        </Box>
        <Box>
          <IconButton color="primary" onClick={() => setIsEditProjectModalOpen(true)}>
            <EditIcon />
          </IconButton>
          <IconButton color="error" onClick={handleDelete}>
            <DeleteIcon />
          </IconButton>
        </Box>
      </Box>

      {/* Stats / Info Grid */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
            <CalendarTodayIcon color="primary" />
            <Box>
              <Typography variant="caption" color="text.secondary">Start Date</Typography>
              <Typography variant="body1">
                {safeFormat(project.start_date, 'MMM d, yyyy')}
              </Typography>
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
            <CalendarTodayIcon color="error" />
            <Box>
              <Typography variant="caption" color="text.secondary">End Date</Typography>
              <Typography variant="body1">
                {safeFormat(project.end_date, 'MMM d, yyyy')}
              </Typography>
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
            <CheckCircleIcon color="success" />
            <Box>
              <Typography variant="caption" color="text.secondary">Status</Typography>
              <Chip
                label={project.status || 'Active'}
                color={project.status === 'Completed' ? 'success' : 'default'}
                size="small"
                sx={{ mt: 0.5 }}
              />
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
            <TrendingUpIcon color="info" />
            <Box sx={{ width: '100%' }}>
              <Typography variant="caption" color="text.secondary">Progress</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <Box sx={{ width: '100%', mr: 1 }}>
                  <LinearProgress variant="determinate" value={progress} />
                </Box>
                <Box sx={{ minWidth: 35 }}>
                  <Typography variant="body2" color="text.secondary">{`${Math.round(progress)}%`}</Typography>
                </Box>
              </Box>
            </Box>
          </Paper>
        </Grid>
      </Grid>

      {/* Gantt Chart Section */}
      <ProjectGanttChart tasks={tasks || []} />


      {/* Task List Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 4, mb: 2 }}>
        <Typography variant="h5" component="h3">
          Tasks & Subtasks
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setIsCreateTaskModalOpen(true)}
        >
          Add Task
        </Button>
      </Box>

      {/* Tasks List */}
      <Box>
        {(!tasks || tasks.length === 0) ? (
          <Paper sx={{ p: 3, textAlign: 'center' }}>
            <Typography color="text.secondary">No tasks found. Create one to get started.</Typography>
          </Paper>
        ) : (
          <Paper>
            <List>
              {tasks.map((task: any) => (
                <React.Fragment key={task.id}>
                  <ListItem
                    sx={{ borderBottom: '1px solid #eee' }}
                  >
                    <ListItemIcon>
                      <CheckCircleIcon color={task.status === 'Completed' ? 'success' : 'disabled'} />
                    </ListItemIcon>
                    <ListItemText
                      primary={
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {task.name}
                          <Chip label={task.status} size="small" variant="outlined" />
                        </Box>
                      }
                      secondary={
                        <>
                          <Typography variant="caption" component="span" sx={{ mr: 2 }}>
                            Due: {safeFormat(task.end_date, 'MMM d')}
                          </Typography>
                          {task.description && <Typography variant="caption" component="span" noWrap >- {task.description}</Typography>}
                        </>
                      }
                    />
                    <IconButton edge="end" onClick={() => handleEditTask(task)} sx={{ ml: 1 }}>
                      <EditIcon />
                    </IconButton>
                    <Button 
                      size="small" 
                      onClick={() => navigate(`/tasks/${task.id}`)}
                      sx={{ ml: 1 }}
                    >
                      Details
                    </Button>
                  </ListItem>

                  {/* Subtasks */}
                  {task.subtasks && task.subtasks.length > 0 && (
                    <List disablePadding sx={{ bgcolor: 'action.hover', pl: 4 }}>
                      {task.subtasks.map((sub: any) => (
                        <ListItem key={`sub-${sub.id}`} dense>
                          <ListItemIcon sx={{ minWidth: 36 }}>
                            <Typography variant="caption" color="text.secondary">↳</Typography>
                          </ListItemIcon>
                          <ListItemText
                            primary={sub.name}
                            secondary={`Status: ${sub.status}`}
                          />
                          {/* Optional: Add edit for subtasks if desired, sticking to main tasks for now as requested by 'enable to modify project or tasks' generally */}
                        </ListItem>
                      ))}
                    </List>
                  )}
                </React.Fragment>
              ))}
            </List>
          </Paper>
        )}
      </Box>

      <CreateTaskModal
        open={isCreateTaskModalOpen}
        onClose={() => setIsCreateTaskModalOpen(false)}
        projectId={parseInt(projectId!)}
        onTaskCreated={() => {
          queryClient.invalidateQueries({ queryKey: ['tasks', projectId] });
          setIsCreateTaskModalOpen(false);
        }}
      />

      <EditProjectModal
        open={isEditProjectModalOpen}
        onClose={() => setIsEditProjectModalOpen(false)}
        project={project}
        onProjectUpdated={() => {
          queryClient.invalidateQueries({ queryKey: ['project', projectId] });
        }}
      />

      <EditTaskModal
        open={isEditTaskModalOpen}
        onClose={() => setIsEditTaskModalOpen(false)}
        task={selectedTask}
        onTaskUpdated={() => {
          queryClient.invalidateQueries({ queryKey: ['tasks', projectId] });
        }}
      />

    </Container>
  );
};

export default ProjectDetailPage;

import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    MenuItem,
    Grid
} from '@mui/material';
import { updateProject } from '../../services/projects';

interface EditProjectModalProps {
    open: boolean;
    onClose: () => void;
    project: any; // Using any for simplicity, ideally strictly typed
    onProjectUpdated: () => void;
}

const EditProjectModal: React.FC<EditProjectModalProps> = ({ open, onClose, project, onProjectUpdated }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (project) {
            setName(project.name || '');
            setDescription(project.description || '');
            // backend sends ISO string, input type="date" expects YYYY-MM-DD
            setStartDate(project.start_date ? project.start_date.split('T')[0] : '');
            setEndDate(project.end_date ? project.end_date.split('T')[0] : '');
            setStatus(project.status || 'Not Started');
        }
    }, [project, open]);

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Project name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateProject(project.id, {
                name,
                description,
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status
            });
            onProjectUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update project');
        } finally {
            setLoading(false);
        }
    };

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Project</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        autoFocus
                        label="Project Name"
                        fullWidth
                        variant="outlined"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        disabled={loading}
                        required
                    />
                    <TextField
                        label="Description"
                        fullWidth
                        multiline
                        rows={3}
                        variant="outlined"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        disabled={loading}
                    />

                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <TextField
                                label="Start Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="End Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                    </Grid>

                    <TextField
                        select
                        label="Status"
                        fullWidth
                        value={status}
                        onChange={(e) => setStatus(e.target.value)}
                        disabled={loading}
                    >
                        {statuses.map((option) => (
                            <MenuItem key={option} value={option}>
                                {option}
                            </MenuItem>
                        ))}
                    </TextField>
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
};

