              <Chip
                label={project.status || 'Active'}
                color={project.status === 'Completed' ? 'success' : 'default'}
                size="small"
                sx={{ mt: 0.5 }}
              />
            </Box>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
            <TrendingUpIcon color="info" />
            <Box sx={{ width: '100%' }}>
              <Typography variant="caption" color="text.secondary">Progress</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <Box sx={{ width: '100%', mr: 1 }}>
                  <LinearProgress variant="determinate" value={progress} />
                </Box>
                <Box sx={{ minWidth: 35 }}>
                  <Typography variant="body2" color="text.secondary">{`${Math.round(progress)}%`}</Typography>
                </Box>
              </Box>
            </Box>
          </Paper>
        </Grid>
      </Grid>

      {/* Gantt Chart Section */}
      <ProjectGanttChart tasks={tasks || []} />


      {/* Task List Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 4, mb: 2 }}>
        <Typography variant="h5" component="h3">
          Tasks & Subtasks
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setIsCreateTaskModalOpen(true)}
        >
          Add Task
        </Button>
      </Box>

      {/* Tasks List */}
      <Box>
        {(!tasks || tasks.length === 0) ? (
          <Paper sx={{ p: 3, textAlign: 'center' }}>
            <Typography color="text.secondary">No tasks found. Create one to get started.</Typography>
          </Paper>
        ) : (
          <Paper>
            <List>
              {tasks.map((task: any) => (
                <React.Fragment key={task.id}>
                  <ListItem
                    sx={{ borderBottom: '1px solid #eee' }}
                  >
                    <ListItemIcon>
                      <CheckCircleIcon color={task.status === 'Completed' ? 'success' : 'disabled'} />
                    </ListItemIcon>
                    <ListItemText
                      primary={
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {task.name}
                          <Chip label={task.status} size="small" variant="outlined" />
                        </Box>
                      }
                      secondary={
                        <>
                          <Typography variant="caption" component="span" sx={{ mr: 2 }}>
                            Due: {safeFormat(task.end_date, 'MMM d')}
                          </Typography>
                          {task.description && <Typography variant="caption" component="span" noWrap >- {task.description}</Typography>}
                        </>
                      }
                    />
                    <IconButton edge="end" onClick={() => handleEditTask(task)} sx={{ ml: 1 }}>
                      <EditIcon />
                    </IconButton>
                    <Button 
                      size="small" 
                      onClick={() => navigate(`/tasks/${task.id}`)}
                      sx={{ ml: 1 }}
                    >
                      Details
                    </Button>
                  </ListItem>

                  {/* Subtasks */}
                  {task.subtasks && task.subtasks.length > 0 && (
                    <List disablePadding sx={{ bgcolor: 'action.hover', pl: 4 }}>
                      {task.subtasks.map((sub: any) => (
                        <ListItem key={`sub-${sub.id}`} dense>
                          <ListItemIcon sx={{ minWidth: 36 }}>
                            <Typography variant="caption" color="text.secondary">↳</Typography>
                          </ListItemIcon>
                          <ListItemText
                            primary={sub.name}
                            secondary={`Status: ${sub.status}`}
                          />
                          {/* Optional: Add edit for subtasks if desired, sticking to main tasks for now as requested by 'enable to modify project or tasks' generally */}
                        </ListItem>
                      ))}
                    </List>
                  )}
                </React.Fragment>
              ))}
            </List>
          </Paper>
        )}
      </Box>

      <CreateTaskModal
        open={isCreateTaskModalOpen}
        onClose={() => setIsCreateTaskModalOpen(false)}
        projectId={parseInt(projectId!)}
        onTaskCreated={() => {
          queryClient.invalidateQueries({ queryKey: ['tasks', projectId] });
          setIsCreateTaskModalOpen(false);
        }}
      />

      <EditProjectModal
        open={isEditProjectModalOpen}
        onClose={() => setIsEditProjectModalOpen(false)}
        project={project}
        onProjectUpdated={() => {
          queryClient.invalidateQueries({ queryKey: ['project', projectId] });
        }}
      />

      <EditTaskModal
        open={isEditTaskModalOpen}
        onClose={() => setIsEditProjectModalOpen(false)}
        task={selectedTask}
        onTaskUpdated={() => {
          queryClient.invalidateQueries({ queryKey: ['tasks', projectId] });
        }}
      />

    </Container>
  );
};

export default ProjectDetailPage;

