  name: string;
  description?: string;
  start_date?: string;
  end_date?: string;
  status?: string;
}) => {
  try {
    const response = await api.post('/projects/', projectData);
    return response.data;
  } catch (error) {
    console.error('Failed to create project:', error);
    throw error;
  }
};

