  name?: string;
  description?: string;
  start_date?: string;
  end_date?: string;
  status?: string;
}) => {
  try {
    const response = await api.put(`/projects/${projectId}`, projectData);
    return response.data;
  } catch (error) {
    console.error(`Failed to update project ${projectId}:`, error);
    throw error;
  }
};

