                                                    ? `Dates: ${sub.start_date || '?'} - ${sub.end_date || '?'}`
                                                    : "No dates set"}
                                                <br />
                                                <Typography component="span" variant="caption" sx={{ mr: 1 }}>
                                                    Status: {sub.status} | Progress: {sub.progress}%
                                                </Typography>
                                                {sub.tag_ids.length > 0 && (
                                                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                                                        {sub.tag_ids.map(tagId => {
                                                            const tag = availableTags?.find(t => t.id === tagId);
                                                            return tag ? (
                                                                <Chip
                                                                    key={tag.id}
                                                                    label={tag.name}
                                                                    size="small"
                                                                    sx={{ bgcolor: tag.color || undefined, color: tag.color ? 'white' : 'black' }}
                                                                />
                                                            ) : null;
                                                        })}
                                                    </Box>
                                                )}
                                                {sub.topic_ids.length > 0 && (
                                                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                                                        {sub.topic_ids.map(topicId => {
                                                            const topic = availableTopics?.find(t => t.id === topicId);
                                                            return topic ? (
                                                                <Chip
                                                                    key={topic.id}
                                                                    label={topic.name}
                                                                    size="small"
                                                                    variant="outlined"
                                                                />
                                                            ) : null;
                                                        })}
                                                    </Box>
                                                )}
                                            </React.Fragment>
                                        }
                                    />
                                    <ListItemSecondaryAction>
                                        <IconButton edge="end" size="small" onClick={() => handleDeletePendingSubtask(index)}>
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                    </ListItemSecondaryAction>
                                </ListItem>
                            ))}
                            {pendingSubtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks added yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={handleClose} disabled={formLoading} color="inherit">Cancel</Button>
