import React, { createContext, useContext, useState, useMemo, ReactNode } from 'react';
import { createTheme, ThemeProvider as MuiThemeProvider, PaletteMode } from '@mui/material';
import { themeOptions as lightThemeOptions } from '../theme'; // Import your base theme options
import { deepmerge } from '@mui/utils';

// Define theme options for dark mode if distinct from light
const darkThemeOptions = {
  palette: {
    mode: 'dark' as PaletteMode,
    // You can override specific colors for dark mode here
    // For example:
    // primary: {
    //   main: '#90CAF9',
    // },
    // secondary: {
    //   main: '#CE93D8',
    // },
    // background: {
    //   default: '#121212',
    //   paper: '#1E1E1E',
    // },
    // text: {
    //   primary: '#FFFFFF',
    //   secondary: '#B0B0B0',
    // },
  },
};

interface ThemeContextType {
  mode: PaletteMode;
  toggleColorMode: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const useThemeMode = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useThemeMode must be used within a ThemeProvider');
  }
  return context;
};

interface ThemeProviderProps {
  children: ReactNode;
}

export const ThemeModeProvider: React.FC<ThemeProviderProps> = ({ children }) => {
  const [mode, setMode] = useState<PaletteMode>('light'); // Default to light mode

  const toggleColorMode = useMemo(
    () => () => {
      setMode((prevMode) => (prevMode === 'light' ? 'dark' : 'light'));
    },
    [],
  );

  const theme = useMemo(() => {
    // Merge base theme options with mode-specific overrides
    const baseTheme = createTheme(lightThemeOptions);
    const modeSpecificTheme = mode === 'dark' ? createTheme(deepmerge(baseTheme, darkThemeOptions)) : baseTheme;
    // Apply components overrides AFTER merging, as component theming might depend on final palette
    modeSpecificTheme.components = lightThemeOptions.components ? (lightThemeOptions.components(modeSpecificTheme) as any) : {};
    return modeSpecificTheme;
  }, [mode]);

  return (
    <ThemeContext.Provider value={{ mode, toggleColorMode }}>
      <MuiThemeProvider theme={theme}>
        {children}
      </MuiThemeProvider>
    </ThemeContext.Provider>
  );
};

