import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    List,
    ListItem,
    ListItemText,
    ListItemSecondaryAction,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    OutlinedInput,
    Chip,
    CircularProgress,
    Autocomplete
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import { createTask } from '../../services/tasks';
import { createSubtask } from '../../services/subtasks';
import { getUsers } from '../../services/users';
import { useAuth } from '../../context/AuthContext';
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { Tag } from '../../types/tag';
import { Topic } from '../../types/topic';
import { useQuery } from '@tanstack/react-query';


interface CreateTaskModalProps {
    open: boolean;
    onClose: () => void;
    projectId: string | number;
    onTaskCreated: () => void;
}

interface PendingSubtask {
    id?: number; // Will be set after creation, for now it's just pending
    name: string;
    description?: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    status: string;
    progress: number;
    tag_ids: number[];
    topic_ids: number[];
    parent_subtask_id?: number; // For nested subtasks
    nested_subtasks: PendingSubtask[];
}

const CreateTaskModal: React.FC<CreateTaskModalProps> = ({ open, onClose, projectId, onTaskCreated }) => {
    // Task State
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [promoterId, setPromoterId] = useState<number | null>(null); // Changed to null
    const [assigneeIds, setAssigneeIds] = useState<number[]>([]);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);

    // Data
    const [users, setUsers] = useState<any[]>([]);

    // Subtask State
    const [pendingSubtasks, setPendingSubtasks] = useState<PendingSubtask[]>([]);
    const [newSubtaskName, setNewSubtaskName] = useState('');
    const [newSubtaskDescription, setNewSubtaskDescription] = useState('');
    const [newSubtaskOwnerId, setNewSubtaskOwnerId] = useState<number | ''>('');
    const [newSubtaskStart, setNewSubtaskStart] = useState('');
    const [newSubtaskEnd, setNewSubtaskEnd] = useState('');
    const [newSubtaskProgress, setNewSubtaskProgress] = useState<number>(0);
    const [newSubtaskStatus, setNewSubtaskStatus] = useState('Not Started');
    const [newSubtaskTags, setNewSubtaskTags] = useState<Tag[]>([]);
    const [newSubtaskTopics, setNewSubtaskTopics] = useState<Topic[]>([]);
    const [newSubtaskParentSubtaskId, setNewSubtaskParentSubtaskId] = useState<number | ''>(''); // For nested subtasks
    const [isAddingSubtask, setIsAddingSubtask] = useState(false);

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const { user } = useAuth();

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });


    useEffect(() => {
        if (open) {
            fetchUsers();
        } else {
            resetForm();
        }
    }, [open]);

    const fetchUsers = async () => {
        try {
            const data = await getUsers();
            setUsers(data);
        } catch (err) {
            console.error("Failed to fetch users", err);
        }
    };

    const resetForm = () => {
        setName('');
        setDescription('');
        setStartDate('');
        setEndDate('');
        setStatus('Not Started');
        setPromoterId(null);
        setAssigneeIds([]);
        setPendingSubtasks([]);
        setNewSubtaskName('');
        setNewSubtaskDescription('');
        setNewSubtaskOwnerId('');
        setNewSubtaskStart('');
        setNewSubtaskEnd('');
        setNewSubtaskProgress(0);
        setNewSubtaskStatus('Not Started');
        setNewSubtaskTags([]);
        setNewSubtaskTopics([]);
        setNewSubtaskParentSubtaskId('');
        setIsAddingSubtask(false);
        setSelectedTags([]);
        setSelectedTopics([]);
        setError('');
    };

    const handleAddSubtask = () => {
        if (!newSubtaskName.trim()) {
            setError('Subtask name cannot be empty.');
            return;
        }
        if (!newSubtaskOwnerId) {
            setError('Subtask owner is required.');
            return;
        }
        if (!user || !user.id) {
            setError('You must be logged in to create a subtask.'); // Added check
            return;
        }
        
        const newSubtask: PendingSubtask = {
            name: newSubtaskName,
            description: newSubtaskDescription || undefined,
            owner_id: Number(newSubtaskOwnerId),
            start_date: newSubtaskStart || undefined,
            end_date: newSubtaskEnd || undefined,
            status: newSubtaskStatus,
            progress: newSubtaskProgress,
            tag_ids: newSubtaskTags.map(t => t.id),
            topic_ids: newSubtaskTopics.map(t => t.id),
            parent_subtask_id: newSubtaskParentSubtaskId === '' ? undefined : Number(newSubtaskParentSubtaskId),
            nested_subtasks: [] // Initialize as empty array
        };

        const addRecursive = (subs: PendingSubtask[], newSub: PendingSubtask, parentId?: number | '') => {
            if (!parentId || parentId === '') {
                return [...subs, newSub];
            }
            return subs.map(s => 
                (s.id === parentId || (s.id === undefined && s.name === subs[parentId as number].name)) // crude match for pending
                    ? { ...s, nested_subtasks: addRecursive(s.nested_subtasks, newSub, undefined) } // Add to its children
                    : { ...s, nested_subtasks: addRecursive(s.nested_subtasks, newSub, parentId) }
            );
        };

        // Simplified: find and add to the correct parent in the flat list for now.
        // A truly recursive add for pending state would be more complex.
        // For current purpose, add to the main list or a direct child of a top-level pending subtask.
        // Since pendingSubtasks are flat, will add to the top level for now or directly append.
        if (newSubtaskParentSubtaskId !== '') {
            // Find the parent by index (since no IDs yet for pending) and add to its nested_subtasks
            const parentIndex = Number(newSubtaskParentSubtaskId);
            const updatedPending = [...pendingSubtasks];
            if (updatedPending[parentIndex]) {
                updatedPending[parentIndex].nested_subtasks.push({ ...newSubtask, parent_subtask_id: undefined }); // Clear parent_subtask_id as it's now nested
                setPendingSubtasks(updatedPending);
            } else {
                setPendingSubtasks([...pendingSubtasks, newSubtask]); // Fallback: add to top level
            }
        } else {
            setPendingSubtasks([...pendingSubtasks, newSubtask]);
        }


        setNewSubtaskName('');
        setNewSubtaskDescription('');
        setNewSubtaskOwnerId('');
        setNewSubtaskStart('');
        setNewSubtaskEnd('');
        setNewSubtaskProgress(0);
        setNewSubtaskStatus('Not Started');
        setNewSubtaskTags([]);
        setNewSubtaskTopics([]);
        setNewSubtaskParentSubtaskId('');
        setIsAddingSubtask(false);
        setError('');
    };

    const handleDeletePendingSubtask = (index: number) => {
        const updated = [...pendingSubtasks];
        updated.splice(index, 1);
        setPendingSubtasks(updated);
    };

    const createSubtasksRecursive = async (parentId: number, subs: PendingSubtask[], isParentTask: boolean) => {
        for (const sub of subs) {
            let createdSubtask;
            if (isParentTask) { // Parent is a Task
                createdSubtask = await createSubtask(parentId, {
                    name: sub.name,
                    description: sub.description,
                    owner_id: sub.owner_id,
                    start_date: sub.start_date ? new Date(sub.start_date).toISOString() : undefined,
                    end_date: sub.end_date ? new Date(sub.end_date).toISOString() : undefined,
                    status: sub.status,
                    progress: sub.progress,
                    tag_ids: sub.tag_ids,
                    topic_ids: sub.topic_ids,
                });
            } else { // Parent is a Subtask (parentId is parent_subtask_id)
                createdSubtask = await createSubtask(sub.parent_task_id!, { // Need the grand-parent task_id
                    name: sub.name,
                    description: sub.description,
                    owner_id: sub.owner_id,
                    start_date: sub.start_date ? new Date(sub.start_date).toISOString() : undefined,
                    end_date: sub.end_date ? new Date(sub.end_date).toISOString() : undefined,
                    status: sub.status,
                    progress: sub.progress,
                    tag_ids: sub.tag_ids,
                    topic_ids: sub.topic_ids,
                    parent_subtask_id: parentId // Set parent_subtask_id
                });
            }

            if (createdSubtask && sub.nested_subtasks.length > 0) {
                await createSubtasksRecursive(createdSubtask.id, sub.nested_subtasks, false);
            }
        }
    };

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Task name is required');
            return;
        }

        if (!user || !user.id) {
            setError('You must be logged in to create a task');
            return;
        }

        setLoading(true);
        setError('');

        try {
            // 1. Create the Task
            const newTask = await createTask(projectId, {
                name,
                description,
                project_id: Number(projectId),
                owner_id: user.id,
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                promoter_id: promoterId,
                assignee_ids: assigneeIds,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
            });

            // 2. Create Subtasks if any
            if (pendingSubtasks.length > 0 && newTask.id) {
                await createSubtasksRecursive(newTask.id, pendingSubtasks, true);
            }

            onTaskCreated();
            onClose(); // resetForm called via useEffect dependency on open
        } catch (err) {
            console.error(err);
            setError('Failed to create task (or subtasks)');
        } finally {
            setLoading(false);
        }
    };

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];
    const formLoading = loading || isLoadingTags || isLoadingTopics;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Create New Task</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                {formLoading && <CircularProgress size={20} sx={{ mr: 1 }} />}

                <Grid container spacing={3}>
                    {/* Left Column: Task Details */}
                    <Grid item xs={12} md={6}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                            <Typography variant="h6" sx={{ mb: 1 }}>Details</Typography>
                            <TextField
                                autoFocus
                                label="Task Name"
                                fullWidth
                                variant="outlined"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                disabled={formLoading}
                                required
                            />
                            <TextField
                                label="Description"
                                fullWidth
                                multiline
                                rows={3}
                                variant="outlined"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                disabled={formLoading}
                            />

                            <Grid container spacing={2}>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Start Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        disabled={formLoading}
                                    />
                                </Grid>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Due Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        disabled={formLoading}
                                    />
                                </Grid>
                            </Grid>

                            <TextField
                                select
                                label="Status"
                                fullWidth
                                value={status}
                                onChange={(e) => setStatus(e.target.value)}
                                disabled={formLoading}
                            >
                                {statuses.map((option) => (
                                    <MenuItem key={option} value={option}>
                                        {option}
                                    </MenuItem>
                                ))}
                            </TextField>

                            </FormControl>

                            <Autocomplete
                                id="promoter-select"
                                options={users}
                                getOptionLabel={(option) => option.email}
                                value={users.find(u => u.id === promoterId) || null}
                                onChange={(_, newValue) => setPromoterId(newValue ? newValue.id : '')}
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Promoter / Lead"
                                        placeholder="Select promoter"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <FormControl fullWidth>
                                <InputLabel id="assignees-label">Assignees (Team)</InputLabel>
                                <Select
                                    labelId="assignees-label"
                                    multiple
                                    value={assigneeIds}
                                    onChange={(e) => setAssigneeIds(typeof e.target.value === 'string' ? e.target.value.split(',').map(Number) : e.target.value as number[])}
                                    input={<OutlinedInput id="select-multiple-chip" label="Assignees (Team)" />}
                                    renderValue={(selected) => (
                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                            {selected.map((value) => {
                                                const u = users.find(user => user.id === value);
                                                return <Chip key={value} label={u ? u.email : value} size="small" />;
                                            })}
                                        </Box>
                                    )}
                                >
                                    {users.map((u) => (
                                        <MenuItem key={u.id} value={u.id}>
                                            {u.email}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <Autocomplete
                                multiple
                                id="task-tags-select"
                                options={availableTags || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTags}
                                onChange={(_, newValue) => setSelectedTags(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Tags"
                                        placeholder="Select tags"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <Autocomplete
                                multiple
                                id="task-topics-select"
                                options={availableTopics || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTopics}
                                onChange={(_, newValue) => setSelectedTopics(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Topics"
                                        placeholder="Select topics"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />
                        </Box>
                    </Grid>

                    {/* Right Column: Subtasks */}
                    <Grid item xs={12} md={6}>
                        <Typography variant="h6" sx={{ mb: 2 }}>Subtasks</Typography>
                        <Box sx={{ mb: 2 }}>
                            {isAddingSubtask ? (
                                <Box sx={{ p: 2, border: '1px solid #ddd', borderRadius: 2 }}>
                                    <TextField
                                        label="Subtask Name"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskName}
                                        onChange={(e) => setNewSubtaskName(e.target.value)}
                                        required
                                    />
                                    <TextField
                                        label="Description"
                                        size="small"
                                        fullWidth
                                        multiline
                                        rows={2}
                                        sx={{ mb: 2 }}
                                        value={newSubtaskDescription}
                                        onChange={(e) => setNewSubtaskDescription(e.target.value)}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Owner</InputLabel>
                                        <Select
                                            value={newSubtaskOwnerId}
                                            label="Owner"
                                            onChange={(e) => setNewSubtaskOwnerId(Number(e.target.value))}
                                            required
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {users.map((u) => (
                                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <TextField
                                        select
                                        label="Status"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskStatus}
                                        onChange={(e) => setNewSubtaskStatus(e.target.value)}
                                    >
                                        {statuses.map((option) => (
                                            <MenuItem key={option} value={option}>
                                                {option}
                                            </MenuItem>
                                        ))}
                                    </TextField>
                                    <Box sx={{ mb: 2 }}>
                                        <Typography variant="caption" gutterBottom>Progress: {newSubtaskProgress}%</Typography>
                                        <Slider
                                            value={newSubtaskProgress}
                                            onChange={(_, val) => setNewSubtaskProgress(val as number)}
                                            min={0}
                                            max={100}
                                            step={1}
                                            valueLabelDisplay="auto"
                                        />
                                    </Box>
                                    <Grid container spacing={1} sx={{ mb: 2 }}>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="Start"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskStart}
                                                onChange={(e) => setNewSubtaskStart(e.target.value)}
                                            />
                                        </Grid>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="End"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskEnd}
                                                onChange={(e) => setNewSubtaskEnd(e.target.value)}
                                            />
                                        </Grid>
                                    </Grid>
                                     <Autocomplete
                                        multiple
                                        id="subtask-tags-select"
                                        options={availableTags || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTags}
                                        onChange={(_, newValue) => setNewSubtaskTags(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Tags"
                                                placeholder="Select tags"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <Autocomplete
                                        multiple
                                        id="subtask-topics-select"
                                        options={availableTopics || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTopics}
                                        onChange={(_, newValue) => setNewSubtaskTopics(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Topics"
                                                placeholder="Select topics"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Parent Subtask (optional)</InputLabel>
                                        <Select
                                            value={newSubtaskParentSubtaskId}
                                            label="Parent Subtask (optional)"
                                            onChange={(e) => setNewSubtaskParentSubtaskId(Number(e.target.value))}
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {pendingSubtasks.map((sub, index) => (
                                                <MenuItem key={index} value={index}>{sub.name}</MenuItem> // Using index as value for pending subtasks
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                        <Button size="small" onClick={() => setIsAddingSubtask(false)}>Cancel</Button>
                                        <Button size="small" variant="contained" onClick={handleAddSubtask}>Add</Button>
                                    </Box>
                                </Box>
                            ) : (
                                <Button startIcon={<AddIcon />} fullWidth variant="outlined" onClick={() => setIsAddingSubtask(true)}>
                                    Add Subtask
                                </Button>
                            )}
                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            {pendingSubtasks.map((sub, index) => (
                                <ListItem key={index} divider>
                                    <ListItemText
                                        primary={sub.name}
                                        secondary={
                                            sub.start_date || sub.end_date
                                                ? `${sub.start_date || '?'} - ${sub.end_date || '?'}`
                                                : "No dates set"
                                        }
                                    />
                                    <ListItemSecondaryAction>
                                        <IconButton edge="end" size="small" onClick={() => handleDeletePendingSubtask(index)}>
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                    </ListItemSecondaryAction>
                                </ListItem>
                            ))}
                            {pendingSubtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks added yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={formLoading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={formLoading}
                    sx={{ px: 4 }}
                >
                    Create Task
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default CreateTaskModal;

import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    IconButton,
    List,
    ListItem,
    ListItemText,
    ListItemSecondaryAction,
    Select,
    InputLabel,
    FormControl,
    OutlinedInput,
    Chip,
    Checkbox,
    ListItemIcon,
    Slider, // Import Slider
    Autocomplete,
    CircularProgress
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import SyncIcon from '@mui/icons-material/Sync';
import EditIcon from '@mui/icons-material/Edit'; // Import EditIcon
import { updateTask } from '../../services/tasks';
import { getSubtasks, createSubtask, deleteSubtask, updateSubtask, Subtask } from '../../services/subtasks';
import { getUsers } from '../../services/users';
import { useAuth } from '../../context/AuthContext';
import { format, isValid, parseISO, min, max } from 'date-fns';
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { Tag } from '../../types/tag';
import { Topic } from '../../types/topic';
import { useQuery } from '@tanstack/react-query';


interface EditTaskModalProps {
    open: boolean;
    onClose: () => void;
    task: any;
    onTaskUpdated: () => void;
}

const EditTaskModal: React.FC<EditTaskModalProps> = ({ open, onClose, task, onTaskUpdated }) => {
    // Task State
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [promoterId, setPromoterId] = useState<number | null>(null); // Changed to null
    const [assigneeIds, setAssigneeIds] = useState<number[]>([]);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);
    
    // Data
    const [users, setUsers] = useState<any[]>([]);

    // Subtask State
    const [subtasks, setSubtasks] = useState<Subtask[]>([]);
    const [newSubtaskName, setNewSubtaskName] = useState('');
    const [newSubtaskDescription, setNewSubtaskDescription] = useState('');
    const [newSubtaskOwnerId, setNewSubtaskOwnerId] = useState<number | ''>('');
    const [newSubtaskStart, setNewSubtaskStart] = useState('');
    const [newSubtaskEnd, setNewSubtaskEnd] = useState('');
    const [newSubtaskProgress, setNewSubtaskProgress] = useState<number>(0);
    const [newSubtaskStatus, setNewSubtaskStatus] = useState('Not Started');
    const [isAddingSubtask, setIsAddingSubtask] = useState(false);
    const [editingSubtask, setEditingSubtask] = useState<Subtask | null>(null); // State for editing existing subtask

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const { user } = useAuth();

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });

    useEffect(() => {
        if (open) {
            fetchUsers();
        }
    }, [open]);

    useEffect(() => {
        if (task && open) {
            setName(task.name || '');
            setDescription(task.description || '');
            setStartDate(task.start_date ? task.start_date.split('T')[0] : '');
            setEndDate(task.end_date ? task.end_date.split('T')[0] : '');
            setStatus(task.status || 'Not Started');
            setPromoterId(task.promoter_id || null); // Initialize with null
            setAssigneeIds(task.assignees ? task.assignees.map((u: any) => u.id) : []);
            setSelectedTags(task.tags || []);
            setSelectedTopics(task.topics || []);
            fetchSubtasks();
        }
    }, [task, open]);

    const fetchUsers = async () => {
        try {
            const data = await getUsers();
            setUsers(data);
        } catch (err) {
            console.error("Failed to fetch users", err);
        }
    };

    const fetchSubtasks = async () => {
        try {
            if (task?.id) {
                const data = await getSubtasks(task.id);
                setSubtasks(data);
            }
        } catch (err) {
            console.error("Failed to load subtasks", err);
        }
    };

    // Calculate Min/Max from Subtasks
    const getSuggestedDates = () => {
        if (subtasks.length === 0) return null;

        const validStartDates = subtasks
            .map(s => s.start_date ? parseISO(s.start_date) : null)
            .filter((d): d is Date => isValid(d));

        const validEndDates = subtasks
            .map(s => s.end_date ? parseISO(s.end_date) : null)
            .filter((d): d is Date => isValid(d));

        if (validStartDates.length === 0 && validEndDates.length === 0) return null;

        const minStart = validStartDates.length > 0 ? min(validStartDates) : null;
        const maxEnd = validEndDates.length > 0 ? max(validEndDates) : null;

        return {
            start: minStart ? format(minStart, 'yyyy-MM-dd') : '',
            end: maxEnd ? format(maxEnd, 'yyyy-MM-dd') : ''
        };
    };

    const handleSyncDates = () => {
        const suggestions = getSuggestedDates();
        if (suggestions) {
            if (suggestions.start) setStartDate(suggestions.start);
            if (suggestions.end) setEndDate(suggestions.end);
        }
    };

    const handleAddSubtask = async () => {
        if (!newSubtaskName.trim()) return;
        if (!user) return;

        try {
            await createSubtask(task.id, {
                title: newSubtaskName,
                description: newSubtaskDescription || undefined,
                owner_id: newSubtaskOwnerId === '' ? user.id : Number(newSubtaskOwnerId), // Default to current user
                start_date: newSubtaskStart ? new Date(newSubtaskStart).toISOString() : undefined,
                end_date: newSubtaskEnd ? new Date(newSubtaskEnd).toISOString() : undefined,
                status: newSubtaskStatus,
                progress: newSubtaskProgress
            });
            setNewSubtaskName('');
            setNewSubtaskDescription('');
            setNewSubtaskOwnerId('');
            setNewSubtaskStart('');
            setNewSubtaskEnd('');
            setNewSubtaskProgress(0);
            setNewSubtaskStatus('Not Started');
            setIsAddingSubtask(false);
            fetchSubtasks();
        } catch (err) {
            console.error(err);
            setError("Failed to add subtask");
        }
    };

    const handleDeleteSubtask = async (id: string | number) => {
        if (!window.confirm("Delete subtask?")) return;
        try {
            await deleteSubtask(id);
            fetchSubtasks();
        } catch (err) {
            console.error(err);
        }
    };

    const handleToggleSubtask = async (sub: Subtask) => {
        try {
            const newStatus = sub.status === 'Completed' ? 'Not Started' : 'Completed';
            await updateSubtask(sub.id, { status: newStatus });
            // Optimistic update or refetch
            setSubtasks(prev => prev.map(s => s.id === sub.id ? { ...s, status: newStatus } : s));
        } catch (err) {
            console.error("Failed to update subtask status", err);
            setError("Failed to update subtask status");
        }
    };

    const handleEditSubtask = (subtaskToEdit: Subtask) => {
        setEditingSubtask(subtaskToEdit);
    };

    const handleSubtaskUpdated = () => {
        fetchSubtasks(); // Refetch subtasks to get latest data
        setEditingSubtask(null); // Close editor
    };

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Task name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateTask(task.id, {
                name,
                description,
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                promoter_id: promoterId,
                assignee_ids: assigneeIds,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
            });
            onTaskUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update task');
        } finally {
            setLoading(false);
        }
    };

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];
    const suggestions = getSuggestedDates();
    const formLoading = loading || isLoadingTags || isLoadingTopics;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Task</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

                <Grid container spacing={3}>
                    {/* Left Column: Task Details */}
                    <Grid item xs={12} md={6}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                            {/* ... (Previous Fields) ... */}
                            <Typography variant="h6" sx={{ mb: 1 }}>Details</Typography>
                            <TextField
                                label="Task Name"
                                fullWidth
                                variant="outlined"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                disabled={loading}
                                required
                            />
                            <TextField
                                label="Description"
                                fullWidth
                                multiline
                                rows={3}
                                variant="outlined"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                disabled={loading}
                            />

                            <Grid container spacing={2} alignItems="center">
                                <Grid item xs={6}>
                                    <TextField
                                        label="Start Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        disabled={loading}
                                    />
                                </Grid>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Due Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        disabled={loading}
                                    />
                                </Grid>
                            </Grid>

                            {suggestions && (suggestions.start || suggestions.end) && (
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, bgcolor: 'action.hover', p: 1, borderRadius: 1 }}>
                                    <SyncIcon color="primary" fontSize="small" />
                                    <Typography variant="caption" color="text.secondary">
                                        Suggested: {suggestions.start || '...'} to {suggestions.end || '...'}
                                    </Typography>
                                    <Button size="small" onClick={handleSyncDates}>Apply</Button>
                                </Box>
                            )}

                            <TextField
                                select
                                label="Status"
                                fullWidth
                                value={status}
                                onChange={(e) => setStatus(e.target.value)}
                                disabled={loading}
                            >
                                {statuses.map((option) => (
                                    <MenuItem key={option} value={option}>
                                        {option}
                                    </MenuItem>
                                ))}
                            </TextField>

                            <Autocomplete
                                id="promoter-select"
                                options={users}
                                getOptionLabel={(option) => option.email}
                                value={users.find(u => u.id === promoterId) || null}
                                onChange={(_, newValue) => setPromoterId(newValue ? newValue.id : null)}
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Promoter / Lead"
                                        placeholder="Select promoter"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <FormControl fullWidth>
                                <InputLabel id="assignees-label">Assignees (Team)</InputLabel>
                                <Select
                                    labelId="assignees-label"
                                    multiple
                                    value={assigneeIds}
                                    onChange={(e) => setAssigneeIds(typeof e.target.value === 'string' ? e.target.value.split(',').map(Number) : e.target.value as number[])}
                                    input={<OutlinedInput id="select-multiple-chip" label="Assignees (Team)" />}
                                    renderValue={(selected) => (
                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                            {selected.map((value) => {
                                                const u = users.find(user => user.id === value);
                                                return <Chip key={value} label={u ? u.email : value} size="small" />;
                                            })}
                                        </Box>
                                    )}
                                >
                                    {users.map((u) => (
                                        <MenuItem key={u.id} value={u.id}>
                                            {u.email}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <Autocomplete
                                multiple
                                id="task-tags-select"
                                options={availableTags || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTags}
                                onChange={(_, newValue) => setSelectedTags(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Tags"
                                        placeholder="Select tags"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <Autocomplete
                                multiple
                                id="task-topics-select"
                                options={availableTopics || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTopics}
                                onChange={(_, newValue) => setSelectedTopics(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Topics"
                                        placeholder="Select topics"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />
                        </Box>
                    </Grid>

                    {/* Right Column: Subtasks */}
                    <Grid item xs={12} md={6}>
                        {/* Subtasks UI */}
                        <Typography variant="h6" sx={{ mb: 2 }}>Subtasks</Typography>
                        <Box sx={{ mb: 2 }}>
                            {isAddingSubtask ? (
                                <Box sx={{ p: 2, border: '1px solid #ddd', borderRadius: 2 }}>
                                    <TextField
                                        label="Subtask Name"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskName}
                                        onChange={(e) => setNewSubtaskName(e.target.value)}
                                    />
                                    <Grid container spacing={1} sx={{ mb: 2 }}>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="Start"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskStart}
                                                onChange={(e) => setNewSubtaskStart(e.target.value)}
                                            />
                                        </Grid>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="End"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskEnd}
                                                onChange={(e) => setNewSubtaskEnd(e.target.value)}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                        <Button size="small" onClick={() => setIsAddingSubtask(false)}>Cancel</Button>
                                        <Button size="small" variant="contained" onClick={handleAddSubtask}>Add</Button>
                                    </Box>
                                </Box>
                            ) : (
                                <Button startIcon={<AddIcon />} fullWidth variant="outlined" onClick={() => setIsAddingSubtask(true)}>
                                    Add Subtask
                                </Button>
                            )}
                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            {subtasks.map((sub) => (
                                <ListItem key={sub.id} divider>
                                    <ListItemIcon>
                                        <Checkbox
                                            edge="start"
                                            checked={sub.status === 'Completed'}
                                            onChange={() => handleToggleSubtask(sub)}
                                            tabIndex={-1}
                                            disableRipple
                                        />
                                    </ListItemIcon>
                                    <ListItemText
                                        primary={sub.name}
                                        secondary={
                                            sub.start_date || sub.end_date
                                                ? `${sub.start_date?.split('T')[0] || '?'} - ${sub.end_date?.split('T')[0] || '?'}`
                                                : "No dates set"
                                        }
                                        sx={{ 
                                            textDecoration: sub.status === 'Completed' ? 'line-through' : 'none',
                                            opacity: sub.status === 'Completed' ? 0.6 : 1
                                        }}
                                    />
                                    <ListItemSecondaryAction>
                                        <IconButton edge="end" size="small" onClick={() => handleDeleteSubtask(sub.id)}>
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                        <IconButton edge="end" size="small" onClick={() => handleEditSubtask(sub)}>
                                            <EditIcon fontSize="small" />
                                        </IconButton>
                                    </ListItemSecondaryAction>
                                </ListItem>
                            ))}
                            {subtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
            {editingSubtask && (
                <SubtaskEditor
                    open={Boolean(editingSubtask)}
                    onClose={() => setEditingSubtask(null)}
                    subtask={editingSubtask}
                    onSubtaskUpdated={handleSubtaskUpdated}
                    users={users}
                />
            )}
        </Dialog>
    );
};

export default EditTaskModal;

