import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    Select,
    InputLabel,
    FormControl,
    Slider,
    CircularProgress, // Import CircularProgress
    Autocomplete,     // Import Autocomplete
    Chip              // Import Chip
} from '@mui/material';
import { updateSubtask, Subtask } from '../../services/subtasks';
import { User } from '../../types/user'; // User interface moved to types/user
import { Tag } from '../../types/tag'; // Import Tag type
import { Topic } from '../../types/topic'; // Import Topic type
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { useQuery } from '@tanstack/react-query'; // Import useQuery

interface SubtaskEditorProps {
    open: boolean;
    onClose: () => void;
    subtask: Subtask;
    onSubtaskUpdated: () => void;
    users: User[]; // Pass users list for owner selection
    currentTaskSubtasks: Subtask[]; // Pass all subtasks of the current task for parent selection
}

const SubtaskEditor: React.FC<SubtaskEditorProps> = ({ open, onClose, subtask, onSubtaskUpdated, users, currentTaskSubtasks }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [ownerId, setOwnerId] = useState<number | ''>('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [progress, setProgress] = useState<number>(0);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);
    const [parentSubtaskId, setParentSubtaskId] = useState<number | null>(null);

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]> incessantly({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]> incessantly({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });

    useEffect(() => {
        if (subtask && open) {
            setName(subtask.name || '');
            setDescription(subtask.description || '');
            setOwnerId(subtask.owner_id || '');
            setStartDate(subtask.start_date ? subtask.start_date.split('T')[0] : '');
            setEndDate(subtask.end_date ? subtask.end_date.split('T')[0] : '');
            setStatus(subtask.status || 'Not Started');
            setProgress(subtask.progress || 0);
            setSelectedTags(subtask.tags || []);
            setSelectedTopics(subtask.topics || []);
            setParentSubtaskId(subtask.parent_subtask_id || null);
        }
    }, [subtask, open]);

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Subtask name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateSubtask(subtask.id, {
                name,
                description: description || undefined,
                owner_id: ownerId === '' ? undefined : Number(ownerId),
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                progress,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
                parent_subtask_id: parentSubtaskId,
                // Only set parent_task_id if parent_subtask_id is null, otherwise it should be derived from the parent subtask
                parent_task_id: parentSubtaskId === null ? subtask.parent_task_id : undefined 
            });
            onSubtaskUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update subtask');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Subtask: {subtask?.name}</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        autoFocus
                        label="Subtask Name"
                        fullWidth
                        variant="outlined"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        disabled={loading}
                        required
                    />
                    <TextField
                        label="Description"
                        fullWidth
                        multiline
                        rows={2}
                        variant="outlined"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        disabled={loading}
                    />
                    <FormControl fullWidth>
                        <InputLabel>Owner</InputLabel>
                        <Select
                            value={ownerId}
                            label="Owner"
                            onChange={(e) => setOwnerId(Number(e.target.value))}
                            disabled={loading}
                        >
                            <MenuItem value=""><em>None</em></MenuItem>
                            {users.map((u) => (
                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <TextField
                                label="Start Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="End Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                    </Grid>
                    <FormControl fullWidth>
                        <InputLabel>Status</InputLabel>
                        <Select
                            value={status}
                            label="Status"
                            onChange={(e) => setStatus(e.target.value)}
                            disabled={loading}
                        >
                            {statuses.map((option) => (
                                <MenuItem key={option} value={option}>
                                    {option}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Box>
                        <Typography variant="caption" gutterBottom>Progress: {progress}%</Typography>
                        <Slider
                            value={progress}
                            onChange={(_, val) => setProgress(val as number)}
                            aria-labelledby="progress-slider"
                            min={0}
                            max={100}
                            step={1}
                            valueLabelDisplay="auto"
                            disabled={loading}
                        />
                    </Box>

                    <Autocomplete
                        id="subtask-parent-select"
                        options={availableParentSubtasks}
                        getOptionLabel={(option) => option.name}
                        value={availableParentSubtasks.find(s => s.id === parentSubtaskId) || null}
                        onChange={(_, newValue) => setParentSubtaskId(newValue ? Number(newValue.id) : null)}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Parent Subtask (Optional)"
                                placeholder="Select parent subtask"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-tags-select"
                        options={availableTags || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTags}
                        onChange={(_, newValue) => setSelectedTags(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Tags"
                                placeholder="Select tags"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-topics-select"
                        options={availableTopics || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTopics}
                        onChange={(_, newValue) => setSelectedTopics(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Topics"
                                placeholder="Select topics"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default SubtaskEditor;

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

import crud, schemas, models
from database import get_db
from .auth import get_current_active_user
from utils.permissions import check_project_access

router = APIRouter()

@router.post("/", response_model=schemas.Project, status_code=status.HTTP_201_CREATED)
def create_project(
    project: schemas.ProjectCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    return crud.create_user_project(db=db, project=project, owner_id=current_user.id)

@router.get("/", response_model=list[schemas.Project])
def read_projects(
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
    skip: int = 0,
    limit: int = 100,
):
    projects = crud.get_projects(db, owner_id=current_user.id, skip=skip, limit=limit)
    return projects

@router.get("/{project_id}", response_model=schemas.Project)
def read_project(
    project_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    return check_project_access(db, project_id, current_user.id, min_role="view")

@router.put("/{project_id}", response_model=schemas.Project)
def update_project(
    project_id: int,
    project: schemas.ProjectUpdate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    check_project_access(db, project_id, current_user.id, min_role="edit")
    return crud.update_project(db=db, project_id=project_id, project=project)

@router.delete("/{project_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_project(
    project_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_project = crud.get_project(db, project_id=project_id)
    if db_project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    if db_project.owner_id != current_user.id:
        raise HTTPException(status_code=403, detail="Not authorized to delete this project")
    crud.delete_project(db=db, project_id=project_id)
    return

@router.post("/{project_id}/share", response_model=schemas.ProjectShare, status_code=status.HTTP_201_CREATED)
def share_project(
    project_id: int,
    project_share: schemas.ProjectShareCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_project = crud.get_project(db, project_id=project_id)
    if db_project is None:
        raise HTTPException(status_code=404, detail="Project not found")
    if db_project.owner_id != current_user.id:
        raise HTTPException(status_code=403, detail="Only project owners can share projects")

    # Check if the user to share with exists
    user_to_share_with = crud.get_user(db, user_id=project_share.shared_with_user_id)
    if user_to_share_with is None:
        raise HTTPException(status_code=404, detail="User to share with not found")

    # Check if already shared
    existing_share = db.query(models.ProjectShare).filter(
        models.ProjectShare.project_id == project_id,
        models.ProjectShare.shared_with_user_id == project_share.shared_with_user_id
    ).first()
    if existing_share:
        raise HTTPException(status_code=400, detail="Project already shared with this user")

    project_share.project_id = project_id
    return crud.create_project_share(db=db, project_share=project_share)

@router.get("/{project_id}/permissions", response_model=list[schemas.ProjectShare])
def get_project_permissions(
    project_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    check_project_access(db, project_id, current_user.id, min_role="view")
    return crud.get_project_shares_for_project(db=db, project_id=project_id)

@router.get("/{project_id}/aggregated_tags_topics", response_model=dict[str, list[int]])
def get_aggregated_tags_topics_for_project(
    project_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    check_project_access(db, project_id, current_user.id, min_role="view")

    # Get the project with its tasks and subtasks
    project = crud.get_project_with_tasks_and_subtasks_eager_loaded(db, project_id)
    if not project:
        raise HTTPException(status_code=404, detail="Project not found")

    aggregated_tag_ids = set()
    aggregated_topic_ids = set()

    # Add project's own tags/topics
    aggregated_tag_ids.update([tag.id for tag in project.tags])
    aggregated_topic_ids.update([topic.id for topic in project.topics])

    # Aggregate from tasks and subtasks
    for task in project.tasks:
        aggregated_tag_ids.update([tag.id for tag in task.tags])
        aggregated_topic_ids.update([topic.id for topic in task.topics])
        for subtask in task.subtasks:
            aggregated_tag_ids.update([tag.id for tag in subtask.tags])
            aggregated_topic_ids.update([topic.id for topic in subtask.topics])

    return {
        "tag_ids": list(aggregated_tag_ids),
        "topic_ids": list(aggregated_topic_ids)
    }

@router.get("/summary_gantt/", response_model=list[schemas.Project])
def get_summary_gantt_data(
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    # This endpoint does not require project-specific permissions as it aggregates all user-accessible projects.
    # The CRUD function already filters by user_id for owned/shared projects.
    projects = crud.get_all_projects_with_tasks_and_subtasks_eager_loaded(db, current_user.id)
    return projects

