        # Allow project owners or admins to delete comments as well
        # Determine the parent project of the comment and check permissions
        project_id_to_check = None
        if db_comment.project_id:
            project_id_to_check = db_comment.project_id
        elif db_comment.task_id:
            task = crud.get_task(db, task_id=db_comment.task_id)
            if task:
                project_id_to_check = task.project_id
        elif db_comment.subtask_id:
            subtask = crud.get_subtask(db, subtask_id=db_comment.subtask_id)
            if subtask:
                # Derive project ID, considering nested subtasks
                current_sub = subtask
                while current_sub and current_sub.parent_subtask_id:
                    current_sub = crud.get_subtask(db, subtask_id=current_sub.parent_subtask_id)
                if current_sub and current_sub.parent_task_id:
                    task = crud.get_task(db, task_id=current_sub.parent_task_id)
                    if task: project_id_to_check = task.project_id

        if project_id_to_check:
            check_project_access(db, project_id_to_check, current_user.id, min_role="edit")
        else:
            raise HTTPException(status_code=403, detail="Not authorized to delete this comment")

    crud.delete_comment(db=db, comment_id=comment_id)
    return
